export default function App() {
  return (
    <main className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center px-6">
      <div className="max-w-xl w-full rounded-3xl border border-slate-800 bg-slate-900/70 p-8 shadow-2xl shadow-black/30">
        <p className="text-sm uppercase tracking-[0.3em] text-cyan-400">MediCare Frontend</p>
        <h1 className="mt-4 text-4xl font-bold leading-tight">React + Tailwind scaffold is ready.</h1>
        <p className="mt-4 text-slate-300">
          Next step: add folder structure, auth pages, routing, and protected dashboards.
        </p>
      </div>
    </main>
  );
}
